    {"id": "p3", "kind": "bar", "title": "Status Distribution", "sql": "SELECT \"Status\", COUNT(*) AS cnt FROM scholarship_applicants GROUP BY 1 ORDER BY cnt DESC", "x": "Status", "y": ["cnt"], "unit": ""},
    {"id": "p4", "kind": "table", "title": "Top 5 Schemes by Applicants", "sql": "SELECT \"Name of scheme\", COUNT(*) AS cnt FROM scholarship_applicants GROUP BY 1 ORDER BY cnt DESC LIMIT 5", "unit": ""}
