{
  "title": "Gender Comparison of Improvement",
  "subtitle": "Average sit-up count improvement from baseline to endline by gender",
  "panels": [
    {
      "id": "p1",
      "kind": "bar",
      "title": "Average Sit-ups Improvement by Gender",
      "sql": "SELECT e.Gender, AVG(e.\"Sit ups\" - b.\"Sit ups\") AS avg_improvement FROM endline e JOIN baseline b ON e.\"Child ID\" = b.\"Child ID\" GROUP BY 1 ORDER BY avg_improvement DESC",
      "x": "Gender",
      "y": ["avg_improvement"],
      "unit": ""
    }
