}

{
  "title": "Donations Summary for This Year",
  "subtitle": "Overview of donation amounts, sources, and trends for the current year",
  "panels": [
    {"id": "p1", "kind": "kpi", "title": "Total donations received", "sql": "SELECT SUM(Amount) AS total_amount FROM donor_transactions WHERE \"Date\" LIKE '2023%'", "unit": ""},
    {"id": "p2", "kind": "bar", "title": "Donations by mode", "sql": "SELECT Mode, SUM(Amount) AS total_amount FROM donor_transactions WHERE \"Date\" LIKE '2023%' GROUP BY 1 ORDER BY total_amount DESC", "x": "Mode", "y": ["total_amount"]},
    {"id": "p3", "kind": "bar", "title": "Donations by city", "sql": "SELECT City, SUM(Amount) AS total_amount FROM donor_transactions WHERE \"Date\" LIKE '2023%' GROUP BY 1 ORDER BY total_amount DESC LIMIT 10", "x": "City", "y": ["total_amount"]},
    {"id": "p4", "kind": "line", "title": "Monthly donation trend", "sql": "SELECT strftime('%Y-%m', \"Date\") AS month, SUM(Amount) AS total_amount FROM donor_transactions WHERE \"Date\" LIKE '2023%' GROUP BY 1 ORDER BY 1", "x": "month", "y": ["total_amount"]},
    {"id": "p5", "kind": "pie", "title": "Share of each mode in total donations", "sql": "SELECT Mode, SUM(Amount) * 100.0 / (SELECT SUM(Amount) FROM donor_transactions WHERE \"Date\" LIKE '2023%') AS pct FROM donor_transactions WHERE \"Date\" LIKE '2023%' GROUP BY 1", "x": "Mode", "y": ["pct"], "unit": "%"}
  ],
  "narrative": "The annual report highlights the substantial growth in donations this year, with a total of {{p1}} received across various channels. {{p2}} illustrates the predominant modes of payment, showing that {{p2.y[0][0]}} is the most common method. {{p3}} reveals the top contributing cities, with {{p3.y[0][0]}} leading the contributions. The monthly trend in {{p4}} demonstrates a steady increase, peaking in {{p4.y[0][-1]}}. Finally, {{p5}} provides a clear visual of how each payment mode contributes to the overall donation pool, with {{p5.y[0][0]}} percent coming from {{p5.x[0]}}."
}

