{
  "title": "District Health Dashboard",
  "subtitle": "Comparing key health indicators across districts",
  "panels": [
    {"id": "p1", "kind": "bar", "title": "Children fully vaccinated (% of 12-23 month olds)", "sql": "SELECT District, Children age 12-23 months fully vaccinated (%) AS vacc_rate FROM district_health_factsheet WHERE Source = 'District factsheet' ORDER BY vacc_rate DESC", "x": "District", "y": ["vacc_rate"]},
    {"id": "p2", "kind": "bar", "title": "Children under 5 years who are stunted (%)", "sql": "SELECT District, Children under 5 years who are stunted (%) AS stunted_rate FROM district_health_factsheet WHERE Source = 'District factsheet' ORDER BY stunted_rate DESC", "x": "District", "y": ["stunted_rate"]},
    {"id": "p3", "kind": "bar", "title": "Women age 15-49 years who are literate (%)", "sql": "SELECT District, Women age 15-49 years who are literate (%) AS literacy_rate FROM district_health_factsheet WHERE Source = 'District factsheet' ORDER BY literacy_rate DESC", "x": "District", "y": ["literacy_rate"]},
    {"id": "p4", "kind": "bar", "title": "Institutional births (% of total births)", "sql": "SELECT District, Institutional births (%) AS institutional_rate FROM district_health_factsheet WHERE Source = 'District factsheet' ORDER BY institutional_rate DESC", "x": "District", "y": ["institutional_rate"]}
  ],
  "narrative": "The dashboard presents four key health indicators for each district, allowing a quick visual comparison. {{p1}} shows the percentage of children aged 12-23 months who are fully vaccinated, highlighting districts with higher immunization coverage. {{p2}} reveals the prevalence of stunting among children under five, identifying areas with greater nutritional challenges. {{p3}} displays literacy rates among women aged 15-49, indicating educational attainment across districts. Finally, {{p4}} measures institutional births, reflecting access to healthcare services during delivery. By examining these panels together, stakeholders can pinpoint districts requiring targeted interventions to improve overall health outcomes."
}
